import type { EngineInterface, Register, RenderElement } from 'claude-code'

__IMPORTS__
import type { Theme } from './theme'

/**
 * __TITLE__ alone. (Generated by tools/build.py from shared/single.register.template.ts: edit that.)
 *
 *   /<command>             turns the theme on (the version last chosen, else the first)
 *   /<command> <version>   switches version, where the theme has several (Reaching: clear, classic)
 *   /<command> off         no backdrop from this plugin
 *   /<command> music on|off   play your own tracks from ~/.config/backdrops/music/<theme id>/
 *   /<command> music add [file]   add a track (no file: opens that folder in Finder)
 *
 * The choice is remembered for new sessions.
 */
export type SingleRequest =
  | { kind: 'on' }
  | { kind: 'show'; theme: Theme }
  | { kind: 'off' }
  | { kind: 'music'; on?: boolean }
  | { kind: 'music-add'; path?: string }
  | { kind: 'unknown'; text: string }

export function parseSingle(themes: readonly Theme[], args: string): SingleRequest {
  const add = args.trim().match(/^music\s+add(?:\s+(.+))?$/i)
  if (add !== null) {
    return add[1] === undefined ? { kind: 'music-add' } : { kind: 'music-add', path: add[1] }
  }
  const word = args.trim().toLowerCase()
  if (word === '') {
    return { kind: 'on' }
  }
  if (word === 'off') {
    return { kind: 'off' }
  }
  if (word === 'music' || word === 'music on' || word === 'music off') {
    return word === 'music' ? { kind: 'music' } : { kind: 'music', on: word === 'music on' }
  }
  const theme = themes.find(one => one.version === word || one.id === word)
  return theme === undefined ? { kind: 'unknown', text: args.trim() } : { kind: 'show', theme }
}

const CHOICE_KEY = 'choice'
const MUSIC_KEY = 'music'

const PLUGIN = '__PLUGIN__'
const COMMAND = '__PLUGIN__'
const THEMES: readonly Theme[] = __THEMES__
const PROBLEMS: readonly string[] = __PROBLEMS__
const FIRST: Theme = THEMES[0] as Theme
const VERSIONS = THEMES.map(one => one.version).filter((v): v is string => v !== undefined)
const USAGE = [`/${COMMAND}`, ...VERSIONS.map(v => `/${COMMAND} ${v}`), `/${COMMAND} off`].join(', ')

async function stored($: EngineInterface): Promise<Theme | 'off'> {
  const id = await $.store.get(CHOICE_KEY)
  if (id === 'off') {
    return 'off'
  }
  return THEMES.find(one => one.id === id) ?? FIRST
}

// >>> music: pasted from shared/music.snippet.ts by tools/build.py (edit that file)
// <<< music

let showing: Theme | undefined

/** Plays the theme's own tracks (the person's, from their music folder) while it shows; else stops. */
async function syncMusic($: EngineInterface): Promise<void> {
  const tracks = showing === undefined ? [] : await tracksFor($, showing.id, [])
  await syncPlayer($, (await $.store.get(MUSIC_KEY)) === 'on', tracks, 0.25)
}

async function show($: EngineInterface, choice: Theme | 'off'): Promise<string | undefined> {
  showing = choice === 'off' ? undefined : choice
  let reason: string | undefined
  if (choice === 'off') {
    await $.theme.clear()
  } else {
    const set = await $.theme.set(choice.look)
    reason = set.isDrawn ? undefined : set.reason
  }
  await syncMusic($)
  return reason
}

async function answer($: EngineInterface, args: string): Promise<string> {
  const request = parseSingle(THEMES, args)
  let choice: Theme | 'off'
  switch (request.kind) {
    case 'unknown':
      return `Unknown "${request.text}". Use ${USAGE}, or /${COMMAND} music on|off.`
    case 'music-add': {
      const id = (showing ?? FIRST).id
      if (request.path === undefined) {
        return await openMusicFolder($, id)
      }
      const added = await addTrack($, id, request.path)
      await syncMusic($)
      return `${added} It plays while music is on (/${COMMAND} music on).`
    }
    case 'music': {
      if (request.on !== undefined) {
        await $.store.set(MUSIC_KEY, request.on ? 'on' : 'off')
        await syncMusic($)
      }
      const folder = await musicFolder($, (showing ?? FIRST).id)
      const count = (await tracksFor($, (showing ?? FIRST).id, [])).length
      const state = (await $.store.get(MUSIC_KEY)) === 'on' ? 'on' : 'off'
      return count === 0
        ? `Music is ${state}. ${FIRST.title} has no tracks yet: put audio files (under 4 MB each) in ${folder}.`
        : `Music is ${state}: ${count} track${count === 1 ? '' : 's'} from ${folder}. /${COMMAND} music ${state === 'on' ? 'off' : 'on'} to change it.`
    }
    case 'off':
      choice = 'off'
      break
    case 'on': {
      const was = await stored($)
      choice = was === 'off' ? FIRST : was
      break
    }
    case 'show':
      choice = request.theme
      break
  }
  await $.store.set(CHOICE_KEY, choice === 'off' ? 'off' : choice.id)
  const why = await show($, choice)
  if (choice === 'off') {
    return `${FIRST.title} is off. /${COMMAND} brings it back.`
  }
  const others = VERSIONS.length > 1 ? ` Versions: ${USAGE}.` : ` /${COMMAND} off turns it off.`
  const done = `${choice.title} is on, here and in new sessions.${others}`
  return why === undefined ? done : `${done} (Not drawn yet: ${why})`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: COMMAND,
      description: '__DESCRIPTION__',
      argumentHint: `[${[...VERSIONS, 'off', 'music on|off', 'music add [file]'].join(' | ')}]`,
    })
    const unpainted = PROBLEMS.find(line => line.startsWith("Desktop won't paint"))
    if (unpainted !== undefined) {
      $.ui.toast(unpainted)
    }
    const choice = await stored($)
    // 'off' at start sets nothing: clearing here could wipe another plugin's theme.
    if (choice !== 'off') {
      await show($, choice)
    }
    return next(e)
  })

  // The music waits for a desktop window, and stops when it goes or the session ends.
  on('session.attach', async ($, e, next) => {
    await syncMusic($)
    return next(e)
  })
  on('session.detach', async ($, e, next) => {
    if (e.reason === 'end') {
      stopPlayer()
    } else {
      await syncMusic($)
    }
    return next(e)
  })
  on('session.end', ($, e, next) => {
    stopPlayer()
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    try {
      return { text: await answer($, e.args) }
    } catch (error) {
      return { text: `/${COMMAND} failed: ${error instanceof Error ? error.message : String(error)}` }
    }
  })

  on('ui.render', { component: 'Backdrop' }, ($, e, next) => {
    if ((e.surface !== 'desktop' && e.surface !== 'mobile') || e.props.plugin !== PLUGIN) {
      return next(e)
    }
    const theme = THEMES.find(one => one.id === e.props.scene)
    if (theme === undefined) {
      return next(e)
    }
    const { Svg } = $.ui.resolve(e)
    // A plain image: the backdrop never receives the pointer, so there is nothing to interact with.
    return h(Svg, { source: theme.scene, alt: theme.alt }) as RenderElement
  })
}
